--
-- Name: fn_calcular_multa(integer); Type: FUNCTION; Schema: bribriotecadb; Owner: neondb_owner
--

CREATE FUNCTION bribriotecadb.fn_calcular_multa(p_emprestimo_id integer) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_dias_atraso INT;
BEGIN
    SELECT COALESCE(SUM(GREATEST(COALESCE(ie.data_devolucao, CURRENT_DATE) - e.data_prevista_devolucao, 0)), 0)
    INTO v_dias_atraso
    FROM itens_emprestimos ie
    JOIN emprestimos e ON e.id_emprestimo = ie.emprestimo_id
    WHERE e.id_emprestimo = p_emprestimo_id;

    RETURN v_dias_atraso * 1.00;
END $$;


ALTER FUNCTION bribriotecadb.fn_calcular_multa(p_emprestimo_id integer) OWNER TO neondb_owner;

--
-- Name: fn_exemplares_disponiveis(integer); Type: FUNCTION; Schema: bribriotecadb; Owner: neondb_owner
--

CREATE FUNCTION bribriotecadb.fn_exemplares_disponiveis(p_livro_id integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_total INT;
    v_emprestados INT;
BEGIN
    SELECT quantidade_exemplar INTO v_total
    FROM livros WHERE id_livro = p_livro_id;

    SELECT COUNT(*) INTO v_emprestados
    FROM itens_emprestimos
    WHERE livro_id = p_livro_id AND data_devolucao IS NULL;

    RETURN COALESCE(v_total, 0) - v_emprestados;
END $$;


ALTER FUNCTION bribriotecadb.fn_exemplares_disponiveis(p_livro_id integer) OWNER TO neondb_owner;

--
-- Name: fn_finaliza_emprestimo(); Type: FUNCTION; Schema: bribriotecadb; Owner: neondb_owner
--

CREATE FUNCTION bribriotecadb.fn_finaliza_emprestimo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.data_devolucao IS NOT NULL THEN
        IF NOT EXISTS (
            SELECT 1 FROM itens_emprestimos
            WHERE emprestimo_id = NEW.emprestimo_id AND data_devolucao IS NULL
        ) THEN
            UPDATE emprestimos SET status = 'devolvido'
            WHERE id_emprestimo = NEW.emprestimo_id;
        END IF;
    END IF;

    RETURN NEW;
END $$;


ALTER FUNCTION bribriotecadb.fn_finaliza_emprestimo() OWNER TO neondb_owner;

--
-- Name: fn_valida_disponibilidade(); Type: FUNCTION; Schema: bribriotecadb; Owner: neondb_owner
--

CREATE FUNCTION bribriotecadb.fn_valida_disponibilidade() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_total INT;
    v_emprestados INT;
BEGIN
    SELECT quantidade_exemplar INTO v_total
    FROM livros WHERE id_livro = NEW.livro_id
    FOR UPDATE;

    IF v_total IS NULL THEN
        RAISE EXCEPTION 'Livro não encontrado.';
    END IF;

    SELECT COUNT(*) INTO v_emprestados
    FROM itens_emprestimos
    WHERE livro_id = NEW.livro_id AND data_devolucao IS NULL;

    IF v_total - v_emprestados <= 0 THEN
        RAISE EXCEPTION 'O livro de código % não tem exemplares disponíveis.', NEW.livro_id;
    END IF;

    RETURN NEW;
END $$;


ALTER FUNCTION bribriotecadb.fn_valida_disponibilidade() OWNER TO neondb_owner;

