--
-- Name: vm_estatisticas_por_categoria; Type: MATERIALIZED VIEW; Schema: bribriotecadb; Owner: neondb_owner
--

CREATE MATERIALIZED VIEW bribriotecadb.vm_estatisticas_por_categoria AS
 SELECT c.id_categoria,
    c.nome AS categoria,
    count(DISTINCT l.id_livro) AS total_livros,
    sum(l.quantidade_exemplar) AS total_exemplares,
    count(ie.livro_id) AS total_emprestimos,
    count(DISTINCT e.cliente_id) AS clientes_distintos,
    ( SELECT count(*) AS count
           FROM bribriotecadb.livros l2
          WHERE ((l2.categoria_id = c.id_categoria) AND (NOT (EXISTS ( SELECT 1
                   FROM bribriotecadb.itens_emprestimos ie2
                  WHERE (ie2.livro_id = l2.id_livro)))))) AS livros_nunca_emprestados
   FROM (((bribriotecadb.categorias c
     LEFT JOIN bribriotecadb.livros l ON ((l.categoria_id = c.id_categoria)))
     LEFT JOIN bribriotecadb.itens_emprestimos ie ON ((ie.livro_id = l.id_livro)))
     LEFT JOIN bribriotecadb.emprestimos e ON ((e.id_emprestimo = ie.emprestimo_id)))
  GROUP BY c.id_categoria, c.nome
  ORDER BY (count(ie.livro_id)) DESC
  WITH NO DATA;


ALTER MATERIALIZED VIEW bribriotecadb.vm_estatisticas_por_categoria OWNER TO neondb_owner;

--
-- Name: vm_ranking_clientes; Type: MATERIALIZED VIEW; Schema: bribriotecadb; Owner: neondb_owner
--

CREATE MATERIALIZED VIEW bribriotecadb.vm_ranking_clientes AS
 SELECT cl.id_cliente,
    cl.nome,
    cl.email,
    count(DISTINCT e.id_emprestimo) AS total_emprestimos,
    count(ie.livro_id) AS total_livros_emprestados,
    sum(
        CASE
            WHEN ((e.status)::text = 'atrasado'::text) THEN 1
            ELSE 0
        END) AS total_atrasos,
    ( SELECT max(e2.data_emprestimo) AS max
           FROM bribriotecadb.emprestimos e2
          WHERE (e2.cliente_id = cl.id_cliente)) AS ultimo_emprestimo
   FROM ((bribriotecadb.clientes cl
     JOIN bribriotecadb.emprestimos e ON ((e.cliente_id = cl.id_cliente)))
     JOIN bribriotecadb.itens_emprestimos ie ON ((ie.emprestimo_id = e.id_emprestimo)))
  GROUP BY cl.id_cliente, cl.nome, cl.email
  ORDER BY (count(ie.livro_id)) DESC
  WITH NO DATA;


ALTER MATERIALIZED VIEW bribriotecadb.vm_ranking_clientes OWNER TO neondb_owner;

--
-- Name: vw_disponibilidade_livros; Type: VIEW; Schema: bribriotecadb; Owner: neondb_owner
--

CREATE VIEW bribriotecadb.vw_disponibilidade_livros AS
 SELECT l.id_livro,
    l.titulo AS livro,
    l.isbn,
    COALESCE(c.nome, 'Sem Categoria'::character varying) AS categoria,
    e.nome AS editora,
    a.nome AS autor,
    l.quantidade_exemplar,
    count(ie.livro_id) AS exemplares_emprestados,
    (l.quantidade_exemplar - count(ie.livro_id)) AS exemplares_disponiveis
   FROM ((((bribriotecadb.livros l
     LEFT JOIN bribriotecadb.categorias c ON ((c.id_categoria = l.categoria_id)))
     JOIN bribriotecadb.editoras e ON ((l.editora_id = e.id_editora)))
     JOIN bribriotecadb.autores a ON ((l.autor_id = a.id_autor)))
     LEFT JOIN bribriotecadb.itens_emprestimos ie ON (((ie.livro_id = l.id_livro) AND (ie.data_devolucao IS NULL))))
  GROUP BY l.id_livro, l.titulo, l.isbn, c.nome, e.nome, a.nome, l.quantidade_exemplar
  ORDER BY (l.quantidade_exemplar - count(ie.livro_id));


ALTER VIEW bribriotecadb.vw_disponibilidade_livros OWNER TO neondb_owner;

--
-- Name: vw_emprestimos_atrasados; Type: VIEW; Schema: bribriotecadb; Owner: neondb_owner
--

CREATE VIEW bribriotecadb.vw_emprestimos_atrasados AS
 SELECT e.id_emprestimo,
    cl.nome AS cliente,
    cl.telefone,
    l.titulo AS livro,
    e.data_emprestimo,
    e.data_prevista_devolucao,
    (CURRENT_DATE - e.data_prevista_devolucao) AS dias_atraso,
    ( SELECT count(*) AS count
           FROM bribriotecadb.itens_emprestimos ie2
          WHERE (ie2.emprestimo_id = e.id_emprestimo)) AS total_livros_no_emprestimo
   FROM (((bribriotecadb.emprestimos e
     JOIN bribriotecadb.clientes cl ON ((cl.id_cliente = e.cliente_id)))
     JOIN bribriotecadb.itens_emprestimos ie ON ((ie.emprestimo_id = e.id_emprestimo)))
     JOIN bribriotecadb.livros l ON ((l.id_livro = ie.livro_id)))
  WHERE ((ie.data_devolucao IS NULL) AND (e.data_prevista_devolucao < CURRENT_DATE))
  ORDER BY (CURRENT_DATE - e.data_prevista_devolucao) DESC;


ALTER VIEW bribriotecadb.vw_emprestimos_atrasados OWNER TO neondb_owner;

--
-- Name: vw_livros_mais_emprestados; Type: VIEW; Schema: bribriotecadb; Owner: neondb_owner
--

CREATE VIEW bribriotecadb.vw_livros_mais_emprestados AS
 SELECT l.id_livro,
    l.titulo AS livro,
    l.isbn,
    COALESCE(c.nome, 'Sem Categoria'::character varying) AS categoria,
    e.nome AS editora,
    a.nome AS autor,
    count(ie.livro_id) AS total_emprestimos
   FROM ((((bribriotecadb.livros l
     LEFT JOIN bribriotecadb.categorias c ON ((c.id_categoria = l.categoria_id)))
     JOIN bribriotecadb.editoras e ON ((l.editora_id = e.id_editora)))
     JOIN bribriotecadb.autores a ON ((l.autor_id = a.id_autor)))
     LEFT JOIN bribriotecadb.itens_emprestimos ie ON ((ie.livro_id = l.id_livro)))
  GROUP BY l.id_livro, l.titulo, l.isbn, c.nome, e.nome, a.nome
  ORDER BY (count(ie.livro_id)) DESC
 LIMIT 30;


ALTER VIEW bribriotecadb.vw_livros_mais_emprestados OWNER TO neondb_owner;

